26	/// What one completed re-wrap did: per-table re-encrypted row counts plus the
27	/// KEK generation recorded in `server_metadata`.
28	#[derive(Debug)]
29	pub struct RewrapReport {
30	    /// `(table name, rows re-wrapped)` for every [`SecretFamily`], in sweep order.
31	    pub families: Vec<(&'static str, u64)>,
32	    /// The generation written by this run (previous value + 1).
33	    pub kek_generation: i64,
34	}
35	
36	impl RewrapReport {
37	    /// Total rows re-encrypted across all families.
38	    pub fn total(&self) -> u64 {
39	        self.families.iter().map(|(_, n)| n).sum()
40	    }
41	}
