43	/// Re-encrypt every KEK-wrapped secret from `old_key` to `new_key` in one
44	/// transaction.
45	///
46	/// Fails without writing anything if any stored blob does not decrypt under
47	/// `old_key`. When that happens because the blob already decrypts under
48	/// `new_key`, the error says so — the usual cause is re-running the tool after
49	/// a completed rotation.
50	pub async fn rewrap_master_key(
51	    pool: &SqlitePool,
52	    old_key: &[u8; 32],
53	    new_key: &[u8; 32],
54	) -> anyhow::Result<RewrapReport> {
55	    if old_key == new_key {
56	        anyhow::bail!("old and new master keys are identical; nothing to rotate");
57	    }
58	
59	    let mut tx = pool.begin().await?;
60	
61	    let mut families = Vec::with_capacity(SecretFamily::ALL.len());
62	    for family in SecretFamily::ALL {
63	        let rows = list_wrapped_secrets(&mut *tx, family).await?;
64	        let mut rewrapped = 0u64;
65	        for row in rows {
66	            // The generic-length decrypt/encrypt pair shares the fixed-length envelope, so
67	            // 32-byte key scalars and longer secrets (the 42-byte escrow share envelope)
68	            // re-wrap through one code path.
69	            let plaintext = match crypto::decrypt_secret_bytes(&row.ciphertext, old_key) {
70	                Ok(p) => p,
71	                Err(e) => {
72	                    // Distinguish "wrong old key" from "rotation already done":
73	                    // a blob that decrypts under the NEW key means a prior run
74	                    // committed and the operator is re-running with stale keys.
75	                    if crypto::decrypt_secret_bytes(&row.ciphertext, new_key).is_ok() {
76	                        anyhow::bail!(
77	                            "{} row {} is already encrypted under the NEW key — a previous \
78	                             rotation appears to have completed; no changes were made",
79	                            family.table(),
80	                            row.id
81	                        );
82	                    }
83	                    anyhow::bail!(
84	                        "failed to decrypt {} row {} with the OLD key ({e}); wrong old key? \
85	                         no changes were made",
86	                        family.table(),
87	                        row.id
88	                    );
89	                }
90	            };
91	            let reencrypted = crypto::encrypt_secret_bytes(&plaintext, new_key)
92	                .map_err(|e| anyhow::anyhow!("re-encryption failed: {e}"))?;
93	            update_wrapped_secret(&mut *tx, family, &row.id, &reencrypted).await?;
94	            rewrapped += 1;
95	        }
96	        families.push((family.table(), rewrapped));
97	    }
98	
99	    let kek_generation = get_kek_generation(&mut *tx).await? + 1;
100	    set_kek_generation(&mut *tx, kek_generation).await?;
101	
102	    tx.commit().await?;
103	    Ok(RewrapReport {
104	        families,
105	        kek_generation,
106	    })
107	}
