// pattern: Imperative Shell
//
// The account-holder's notification endpoints:
//
//   POST   /v1/notifications/register               — register this device for push
//   DELETE /v1/notifications/register/{deviceUuid}  — stop pushing to this device
//   GET    /v1/notifications/sender-keys            — the set of keys to pin
//
// Auth is `auth::extractors::authenticate_access` (the DPoP-binding seam every access-token
// verification must route through — `just auth-seam-check` enforces it), so these live on
// the same-origin `/v1/*` surface alongside the other wallet endpoints.
//
// Registration keys on `(did, device_uuid)` rather than the `devices` table: `devices` rows
// are deleted inside the DID-promotion transaction, so a registration anchored there would
// die exactly when the account starts mattering. `device_uuid` is app-generated and stable
// across reinstalls of the same install identity.
//
// The relay round trip is deliberately **not** in the request path. Registration is one of
// the first calls the wallet makes after promotion; making it wait on a third-party relay
// would put that relay's uptime in the onboarding critical path for a feature whose entire
// failure mode is a missed banner. The row is stored, the relay registration is enqueued,
// and the response says plainly which of the two happened.

use axum::{
    extract::{Path, State},
    http::{HeaderMap, Method, Uri},
    Json,
};
use serde::{Deserialize, Serialize};

use crate::app::AppState;
use crate::auth::extractors::authenticate_access;
use crate::auth::validation::validate_device_public_key;
use crate::db::notifications as store;
use crate::notify_relay_client::{NotifyJob, RegistrationOwner};
use common::{ApiError, ErrorCode};

/// Reject when the operator has not configured a relay.
///
/// A 501 rather than a 404: the route exists, this instance has simply not opted into push.
/// The wallet reads that as "notifications unavailable here" and stops asking, which is the
/// honest answer for a self-hoster who never pointed at a relay.
fn require_notifications_enabled(state: &AppState) -> Result<(), ApiError> {
    if state.config.notifications.relay.is_none() {
        return Err(ApiError::new(
            ErrorCode::NotImplemented,
            "this instance is not configured for push notifications",
        ));
    }
    Ok(())
}

/// Validate an APNs device token and topic.
///
/// Both are echoed to Apple by the relay, so they are bounded and charset-checked here rather
/// than trusted: the token is hex, and the topic is a bundle id.
fn validate_apns(token: &str, topic: &str) -> Result<(), ApiError> {
    let invalid = |msg: &str| ApiError::new(ErrorCode::InvalidRequest, msg.to_string());

    if token.is_empty() || token.len() > MAX_APNS_TOKEN_LEN {
        return Err(invalid("apnsToken must be between 1 and 200 characters"));
    }
    if !token.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(invalid("apnsToken must be hexadecimal"));
    }
    if topic.is_empty() || topic.len() > MAX_APNS_TOPIC_LEN {
        return Err(invalid("apnsTopic must be between 1 and 200 characters"));
    }
    if !topic
        .bytes()
        .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
    {
        return Err(invalid("apnsTopic must be a bundle identifier"));
    }
    Ok(())
}

const MAX_APNS_TOKEN_LEN: usize = 200;
const MAX_APNS_TOPIC_LEN: usize = 200;

/// Validate the device's notification public key, which must be a P-256 `did:key`.
///
/// Two layers: the shared length/emptiness guard every device key gets, then an actual
/// decode. Storing a key we cannot decode would turn a bad registration into a permanently
/// undeliverable device that only surfaces at send time.
fn validate_notification_key(public_key: &str) -> Result<(), ApiError> {
    validate_device_public_key(public_key)
        .map_err(|e| ApiError::new(ErrorCode::InvalidRequest, e.replace("devicePublicKey", "notificationPublicKey")))?;
    crypto::p256_public_key_from_did_key(public_key)
        .map(|_| ())
        .map_err(|e| {
            ApiError::new(
                ErrorCode::InvalidRequest,
                format!("notificationPublicKey must be a P-256 did:key ({e})"),
            )
        })
}

// ── POST /v1/notifications/register ───────────────────────────────────────────

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RegisterRequest {
    /// App-generated stable device identifier. Survives DID promotion, unlike `devices.id`.
    pub device_uuid: String,
    /// The device's P-256 notification `did:key`. Payloads are sealed to this.
    pub notification_public_key: String,
    pub apns_token: String,
    pub apns_topic: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RegisterResponse {
    /// Always `"pending"`: the row is stored, and the relay handle is being minted in the
    /// background. The app learns the outcome by re-reading, not by blocking here.
    pub status: &'static str,
}

pub async fn register_notifications(
    State(state): State<AppState>,
    method: Method,
    uri: Uri,
    headers: HeaderMap,
    Json(payload): Json<RegisterRequest>,
) -> Result<Json<RegisterResponse>, ApiError> {
    let user = authenticate_access(&headers, &method, &uri, &state)?;
    require_notifications_enabled(&state)?;

    if payload.device_uuid.is_empty() || payload.device_uuid.len() > MAX_DEVICE_UUID_LEN {
        return Err(ApiError::new(
            ErrorCode::InvalidRequest,
            "deviceUuid must be between 1 and 128 characters",
        ));
    }
    validate_notification_key(&payload.notification_public_key)?;
    validate_apns(&payload.apns_token, &payload.apns_topic)?;

    store::upsert_registration(
        &state.db,
        &user.did,
        &payload.device_uuid,
        &payload.notification_public_key,
        &payload.apns_token,
        &payload.apns_topic,
    )
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "failed to store a notification registration");
        ApiError::new(ErrorCode::InternalError, "failed to store the registration")
    })?;

    if let Some(sender) = state.notify_sender.as_ref() {
        let _ = sender.send(NotifyJob::RegisterHandle {
            owner: RegistrationOwner::Account {
                did: user.did.clone(),
                device_uuid: payload.device_uuid.clone(),
            },
            apns_token: payload.apns_token,
            apns_topic: payload.apns_topic,
        });
    }

    Ok(Json(RegisterResponse { status: "pending" }))
}

const MAX_DEVICE_UUID_LEN: usize = 128;

// ── DELETE /v1/notifications/register/{deviceUuid} ────────────────────────────

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct UnregisterResponse {
    /// `"deleted"` when a registration existed, `"absent"` when there was nothing to remove.
    pub status: &'static str,
}

pub async fn unregister_notifications(
    State(state): State<AppState>,
    method: Method,
    uri: Uri,
    headers: HeaderMap,
    Path(device_uuid): Path<String>,
) -> Result<Json<UnregisterResponse>, ApiError> {
    let user = authenticate_access(&headers, &method, &uri, &state)?;

    // Read the row before deleting so the relay handle can be dropped too — otherwise the
    // relay keeps forwarding to a device this account has explicitly disowned.
    let handle = store::list_registrations(&state.db, &user.did)
        .await
        .ok()
        .and_then(|rows| {
            rows.into_iter()
                .find(|r| r.device_id == device_uuid)
                .and_then(|r| r.push_handle)
        });

    let existed = store::delete_registration(&state.db, &user.did, &device_uuid)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "failed to delete a notification registration");
            ApiError::new(
                ErrorCode::InternalError,
                "failed to delete the registration",
            )
        })?;

    if let (Some(handle), Some(sender)) = (handle, state.notify_sender.as_ref()) {
        let _ = sender.send(NotifyJob::DropHandle { handle });
    }

    Ok(Json(UnregisterResponse {
        // Idempotent: repeating a delete is a 200, not a 404. The app retries this on a flaky
        // network and must not have to distinguish "already gone" from "failed".
        status: if existed { "deleted" } else { "absent" },
    }))
}

// ── GET /v1/notifications/sender-keys ─────────────────────────────────────────

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SenderKey {
    /// Version. The envelope of every sealed payload names which key sealed it.
    pub kid: i64,
    /// The P-256 `did:key` to verify against.
    pub public_key: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SenderKeysResponse {
    pub keys: Vec<SenderKey>,
}

/// The re-pin surface. The app fetches this on every successful Custos contact, which is what
/// keeps the compromise window for a revoked key short: revocation removes a key from this
/// set immediately, and the next contact is the last time a device will trust it.
///
/// Retired keys stay in the set — a payload sealed just before a rotation must still verify
/// on a device that has already re-pinned.
pub async fn get_sender_keys(
    State(state): State<AppState>,
    method: Method,
    uri: Uri,
    headers: HeaderMap,
) -> Result<Json<SenderKeysResponse>, ApiError> {
    authenticate_access(&headers, &method, &uri, &state)?;
    require_notifications_enabled(&state)?;
    Ok(Json(sender_keys_response(&state).await?))
}

/// Shared by both surfaces (this one and the admin one) — the published set is a property of
/// the instance, not of who is asking.
pub(crate) async fn sender_keys_response(
    state: &AppState,
) -> Result<SenderKeysResponse, ApiError> {
    let keys = crate::notifications::published_sender_keys(state)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "failed to load notification sender keys");
            ApiError::new(ErrorCode::InternalError, "failed to load sender keys")
        })?;

    Ok(SenderKeysResponse {
        keys: keys
            .into_iter()
            .map(|(kid, public_key)| SenderKey { kid, public_key })
            .collect(),
    })
}

