170	    State(state): State<AppState>,
171	    method: Method,
172	    uri: Uri,
173	    headers: HeaderMap,
174	) -> Result<Json<SenderKeysResponse>, ApiError> {
175	    authenticate_access(&headers, &method, &uri, &state)?;
176	    require_notifications_enabled(&state)?;
177	    Ok(Json(sender_keys_response(&state).await?))
178	}
