79	        return e.into_response();
80	    }
81	
82	    let payload = match Json::<AdminRegisterRequest>::from_bytes(&body) {
83	        Ok(Json(payload)) => payload,
84	        Err(rejection) => return rejection.into_response(),
85	    };
86	
87	    if let Err(e) = validate_registration_fields(
88	        &payload.notification_public_key,
89	        &payload.apns_token,
90	        &payload.apns_topic,
91	    ) {
92	        return e.into_response();
93	    }
94	
95	    if let Err(e) = store::upsert_admin_registration(
96	        &state.db,
97	        &device_id,
98	        &payload.notification_public_key,
99	        &payload.apns_token,
100	        &payload.apns_topic,
101	    )
102	    .await
103	    {
104	        tracing::error!(error = %e, "failed to store an admin notification registration");
