34	/// Validate everything a registration body carries, on both surfaces.
35	///
36	/// The public key is decoded, not merely length-checked: a key we cannot decode now is a
37	/// device we cannot reach later, and that failure would surface only at send time, far from
38	/// the request that caused it.
39	pub(crate) fn validate_registration_fields(
40	    notification_public_key: &str,
41	    apns_token: &str,
42	    apns_topic: &str,
43	) -> Result<(), ApiError> {
44	    let invalid = |msg: String| ApiError::new(ErrorCode::InvalidRequest, msg);
45	
46	    validate_device_public_key(notification_public_key)
47	        .map_err(|e| invalid(e.replace("devicePublicKey", "notificationPublicKey")))?;
48	    crypto::p256_public_key_from_did_key(notification_public_key)
49	        .map_err(|e| invalid(format!("notificationPublicKey must be a P-256 did:key ({e})")))?;
50	
51	    if apns_token.is_empty() || apns_token.len() > MAX_APNS_FIELD_LEN {
52	        return Err(invalid(format!(
53	            "apnsToken must be between 1 and {MAX_APNS_FIELD_LEN} characters"
54	        )));
55	    }
56	    if !apns_token.bytes().all(|b| b.is_ascii_hexdigit()) {
57	        return Err(invalid("apnsToken must be hexadecimal".to_string()));
58	    }
59	    if apns_topic.is_empty() || apns_topic.len() > MAX_APNS_FIELD_LEN {
60	        return Err(invalid(format!(
61	            "apnsTopic must be between 1 and {MAX_APNS_FIELD_LEN} characters"
62	        )));
63	    }
64	    if !apns_topic
65	        .bytes()
66	        .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
67	    {
68	        return Err(invalid("apnsTopic must be a bundle identifier".to_string()));
69	    }
70	    Ok(())
71	}
