1	// pattern: Imperative Shell
2	//
3	// The pds's first *outbound* iroh leg. Everything else in `iroh_tunnel.rs` accepts; this
4	// dials. It reuses that same bound `Endpoint` — an iroh endpoint both accepts and dials, so
5	// the instance presents one stable node identity to the relay, which is exactly the identity
6	// the relay authorizes against (`connection.remote_id()`; no credential ever travels in a
7	// message).
8	//
9	// Framing mirrors the relay's accept side: one JSON request per bidirectional stream,
10	// delimited by our FIN, one JSON response back, under a per-stream deadline.
11	//
12	// Connections are lazy and cached. A relay that is down must never become a pds outage, so
13	// every failure here is logged and swallowed by the caller (`crate::notifications`), never
14	// propagated into a request path.
15	
16	use std::sync::Arc;
17	use std::time::Duration;
18	
19	use iroh::{Endpoint, EndpointAddr, EndpointId};
20	use notify_relay::protocol::{Request, Response, ALPN, MAX_MESSAGE_LEN};
21	use tokio::sync::Mutex;
22	
23	/// Maximum time for one request/response exchange, matching the relay's own stream deadline.
24	const STREAM_TIMEOUT: Duration = Duration::from_secs(30);
25	
26	/// How long a dial may take before we give up and let the next send retry.
27	const DIAL_TIMEOUT: Duration = Duration::from_secs(15);
28	
29	/// A dialing client for one configured relay.
30	pub struct NotifyRelayClient {
31	    endpoint: Endpoint,
32	    relay_id: EndpointId,
33	    /// The claim code from `[notifications] enrollment_code`, presented on every `enroll`.
34	    /// The relay consumes it once; later enrolls of an already-enrolled node succeed anyway,
35	    /// so re-presenting a spent code is harmless.
36	    enrollment_code: Option<String>,
37	    /// The live connection, if any. Behind an async mutex because establishing one is an
38	    /// `await`: without serializing, a burst of sends after a relay restart would each dial
39	    /// their own connection.
40	    connection: Mutex<Option<iroh::endpoint::Connection>>,
41	}
42	
43	impl NotifyRelayClient {
44	    /// Build a client for `relay_node_id`, dialing from the pds's own endpoint.
45	    ///
46	    /// Fails only if the configured node id is unparseable — a config error worth surfacing
47	    /// at startup rather than as a silent non-delivery later.
48	    pub fn new(
49	        endpoint: Endpoint,
50	        relay_node_id: &str,
51	        enrollment_code: Option<String>,
52	    ) -> anyhow::Result<Self> {
53	        let relay_id: EndpointId = relay_node_id
54	            .parse()
55	            .map_err(|e| anyhow::anyhow!("notifications.relay is not a valid iroh node id: {e}"))?;
56	        Ok(Self {
57	            endpoint,
58	            relay_id,
59	            enrollment_code,
60	            connection: Mutex::new(None),
61	        })
62	    }
63	
64	    /// Send one request and await its response, dialing (and enrolling) as needed.
65	    pub async fn call(&self, request: Request) -> anyhow::Result<Response> {
66	        let response = self.exchange(request.clone()).await?;
67	
68	        // Enrollment is not a startup step: the relay may have been restarted, re-provisioned,
69	        // or reached for the first time mid-run. Rather than tracking enrollment state we let
70	        // the relay tell us, and enroll exactly when it says we must. This is idempotent and
71	        // costs one extra round trip only on the first send after a relay forgets us.
72	        if matches!(response, Response::NotEnrolled) && !matches!(request, Request::Enroll { .. }) {
73	            let enrolled = self
74	                .exchange(Request::Enroll {
75	                    claim_code: self.enrollment_code.clone(),
76	                })
77	                .await?;
78	            if !matches!(enrolled, Response::Ok) {
79	                anyhow::bail!("relay refused enrollment: {enrolled:?}");
80	            }
81	            return self.exchange(request).await;
82	        }
83	
84	        Ok(response)
85	    }
86	
87	    /// One request/response exchange on a fresh stream over the cached connection.
88	    async fn exchange(&self, request: Request) -> anyhow::Result<Response> {
89	        let encoded = serde_json::to_vec(&request)?;
90	
91	        // One retry, because the failure we expect is a *stale* cached connection: the relay
92	        // restarted and our handle to it is dead, which only surfaces when we try to use it.
93	        // Retrying with a fresh dial turns that into a transparent reconnect. A second failure
94	        // is a real outage, and the caller drops the notification.
95	        let mut last_error = None;
96	        for attempt in 0..2 {
97	            let connection = match self.connect(attempt == 1).await {
98	                Ok(c) => c,
99	                Err(e) => {
100	                    last_error = Some(e);
101	                    continue;
102	                }
103	            };
104	            match Self::round_trip(&connection, &encoded).await {
105	                Ok(response) => return Ok(response),
106	                Err(e) => {
107	                    tracing::debug!(error = %e, attempt, "notify relay exchange failed");
108	                    // Drop the connection so the next attempt re-dials rather than reusing
109	                    // something we just proved broken.
110	                    *self.connection.lock().await = None;
111	                    last_error = Some(e);
112	                }
113	            }
114	        }
115	        Err(last_error.unwrap_or_else(|| anyhow::anyhow!("notify relay unreachable")))
116	    }
117	
118	    /// Return the cached connection, dialing a new one if absent (or if `force_redial`).
119	    async fn connect(&self, force_redial: bool) -> anyhow::Result<iroh::endpoint::Connection> {
120	        let mut guard = self.connection.lock().await;
121	        if force_redial {
122	            *guard = None;
123	        }
124	        if let Some(connection) = guard.as_ref() {
125	            return Ok(connection.clone());
126	        }
127	        let connection = tokio::time::timeout(
128	            DIAL_TIMEOUT,
129	            self.endpoint
130	                .connect(EndpointAddr::new(self.relay_id), ALPN),
131	        )
132	        .await
133	        .map_err(|_| anyhow::anyhow!("dialing the notify relay timed out"))?
134	        .map_err(|e| anyhow::anyhow!("failed to dial the notify relay: {e}"))?;
135	        *guard = Some(connection.clone());
136	        Ok(connection)
137	    }
